// SPEC F19 — sprites-as-code. A Sprite is a palette map plus string-row
// frames; '.' is transparent. All art in src/renderer/sprites/ is data of
// this shape and self-registers into the registry below so that
// tests/sprites.test.ts can verify every frame of every sprite.
//
// This module must compile under tsconfig.test (node): the only DOM
// reference is the TYPE-ONLY `Pick<CanvasRenderingContext2D, ...>` alias —
// no DOM value is ever touched at runtime.

/** The transparent character used in frame rows. */
export const TRANSPARENT = '.';

export interface Sprite {
  /** Frame width in game pixels; every row of every frame is exactly this long. */
  w: number;
  /** Frame height in game pixels; every frame has exactly this many rows. */
  h: number;
  /** Maps every non-transparent frame char to a CSS hex color. */
  palette: Record<string, string>;
  /** One string-row matrix per animation frame. */
  frames: string[][];
}

export interface DrawSpriteOptions {
  /** Mirror the frame horizontally (sprites face right by default). */
  flipX?: boolean;
  /** Draw every opaque pixel in this color instead (hit-flash etc.). */
  tint?: string;
  /** Integer pixel scale: every art pixel becomes a scale×scale rect (default 1). */
  scale?: number;
}

/**
 * The minimal canvas surface drawSprite needs. Type-only projection of the
 * DOM context so sprite code stays testable in a node environment; a real
 * CanvasRenderingContext2D satisfies it structurally.
 */
export type SpriteCanvas = Pick<CanvasRenderingContext2D, 'fillStyle' | 'fillRect'>;

/**
 * Paint one frame of a sprite at (x, y) in 1px game-pixel units.
 * Unknown frame indices and palette-less chars are skipped silently —
 * drawing must never throw mid-render-loop.
 */
export function drawSprite(
  ctx: SpriteCanvas,
  sprite: Sprite,
  frame: number,
  x: number,
  y: number,
  opts?: DrawSpriteOptions,
): void {
  const rows = sprite.frames[frame];
  if (rows === undefined) {
    return;
  }
  const scale = opts?.scale ?? 1;
  for (let ry = 0; ry < sprite.h; ry++) {
    const row = rows[ry];
    if (row === undefined) {
      continue;
    }
    for (let rx = 0; rx < sprite.w; rx++) {
      const ch = row.charAt(opts?.flipX === true ? sprite.w - 1 - rx : rx);
      if (ch === TRANSPARENT || ch === '') {
        continue;
      }
      const color = sprite.palette[ch];
      if (color === undefined) {
        continue;
      }
      ctx.fillStyle = opts?.tint ?? color;
      ctx.fillRect(x + rx * scale, y + ry * scale, scale, scale);
    }
  }
}

const registry = new Map<string, Sprite>();

/**
 * Register named sprites. Every art module calls this at load time so the
 * integrity tests cover ALL sprites (T12 additions included) by iterating
 * `allSprites()` — new art modules only need a side-effect import in the
 * test file. Duplicate names throw: silent overwrites would let a frame
 * escape the integrity sweep.
 */
export function registerSprites(entries: Record<string, Sprite>): void {
  for (const [name, sprite] of Object.entries(entries)) {
    if (registry.has(name)) {
      throw new Error(`sprite registered twice: ${name}`);
    }
    registry.set(name, sprite);
  }
}

/** Snapshot of every registered sprite, keyed by registration name. */
export function allSprites(): ReadonlyMap<string, Sprite> {
  return registry;
}
// SPEC F19 — shared color vocabulary for all sprites-as-code, plus the HSL
// tier-tint helper (GAME_ARCHITECTURE §4: species repeat with a hue-shifted
// palette per tier so scaling monsters look new). Pure math — no DOM.

/** DB16 (DawnBringer 16) palette, the base vocabulary for all sprite art. */
export const COLORS = {
  void: '#140c1c',
  maroon: '#442434',
  navy: '#30346d',
  slate: '#4e4a4e',
  brown: '#854c30',
  forest: '#346524',
  red: '#d04648',
  gray: '#757161',
  blue: '#597dce',
  orange: '#d27d2c',
  steel: '#8595a1',
  green: '#6daa2c',
  skin: '#d2aa99',
  cyan: '#6dc2ca',
  yellow: '#dad45e',
  white: '#deeed6',
} as const;

/** Hue degrees added per monster tier by paletteForTier. */
export const TIER_HUE_STEP = 60;

interface Hsl {
  h: number;
  s: number;
  l: number;
}

function clampByte(n: number): number {
  return Math.min(255, Math.max(0, Math.round(n)));
}

/** Parse '#rrggbb' into HSL (h in [0,360), s and l in [0,1]). */
export function hexToHsl(hex: string): Hsl {
  const digits = /^#([0-9a-f]{6})$/i.exec(hex)?.[1];
  if (digits === undefined) {
    throw new Error(`not a #rrggbb color: ${hex}`);
  }
  const int = parseInt(digits, 16);
  const r = ((int >> 16) & 0xff) / 255;
  const g = ((int >> 8) & 0xff) / 255;
  const b = (int & 0xff) / 255;

  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const delta = max - min;
  const l = (max + min) / 2;

  if (delta === 0) {
    return { h: 0, s: 0, l };
  }
  const s = delta / (1 - Math.abs(2 * l - 1));
  let h: number;
  if (max === r) {
    h = ((g - b) / delta) % 6;
  } else if (max === g) {
    h = (b - r) / delta + 2;
  } else {
    h = (r - g) / delta + 4;
  }
  h *= 60;
  if (h < 0) {
    h += 360;
  }
  return { h, s, l };
}

/** Convert HSL (h degrees, s/l in [0,1]) to '#rrggbb'. */
export function hslToHex(h: number, s: number, l: number): string {
  const hue = ((h % 360) + 360) % 360;
  const c = (1 - Math.abs(2 * l - 1)) * s;
  const x = c * (1 - Math.abs(((hue / 60) % 2) - 1));
  const m = l - c / 2;

  let r = 0;
  let g = 0;
  let b = 0;
  if (hue < 60) {
    r = c;
    g = x;
  } else if (hue < 120) {
    r = x;
    g = c;
  } else if (hue < 180) {
    g = c;
    b = x;
  } else if (hue < 240) {
    g = x;
    b = c;
  } else if (hue < 300) {
    r = x;
    b = c;
  } else {
    r = c;
    b = x;
  }

  const toHex = (v: number): string => clampByte((v + m) * 255).toString(16).padStart(2, '0');
  return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

/** Rotate a '#rrggbb' color's hue by `degrees`, keeping saturation/lightness. */
export function shiftHue(hex: string, degrees: number): string {
  const { h, s, l } = hexToHsl(hex);
  if (s === 0) {
    return hex.toLowerCase(); // grayscale has no hue to rotate
  }
  return hslToHex(h + degrees, s, l);
}

/** Hue-rotate every color of a sprite palette by the same amount. */
export function tintPalette(palette: Record<string, string>, degrees: number): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [ch, color] of Object.entries(palette)) {
    out[ch] = shiftHue(color, degrees);
  }
  return out;
}

/**
 * Palette variant for a monster tier (tier = floor(monsterIndex / 5), see
 * core/monsters.ts). Tier 0 is the sprite's own palette, untouched; each
 * later tier rotates hue by TIER_HUE_STEP degrees.
 */
export function paletteForTier(palette: Record<string, string>, tier: number): Record<string, string> {
  const step = Math.max(0, Math.floor(tier)) * TIER_HUE_STEP;
  if (step % 360 === 0) {
    return { ...palette };
  }
  return tintPalette(palette, step);
}
// Easing helpers + a fixed-cap particle pool (T14; Manual M2/M3 polish),
// plus the T15 presentation math: monster death pixel-scatter, level-up
// sparkles and the pooled item-drop flight (parabolic arc + bounce, then
// fly to the HUD counter). Presentation-only and DOM-free: everything draws
// through SpriteCanvas so tests run under vitest's node environment (same
// policy as game.ts/hud.ts).

import { COLORS, TRANSPARENT } from './sprites/index.js';
import type { Sprite, SpriteCanvas } from './sprites/index.js';

/** Clamp a number into [0, 1]; non-finite input counts as 0. */
export function clamp01(t: number): number {
  if (!Number.isFinite(t) || t <= 0) {
    return 0;
  }
  return t >= 1 ? 1 : t;
}

/** Linear interpolation from a to b by clamped t. */
export function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * clamp01(t);
}

/** Quadratic ease-in: slow start, fast finish (item fly-to-HUD, T15). */
export function easeInQuad(t: number): number {
  const c = clamp01(t);
  return c * c;
}

/** Quadratic ease-out: fast start, slow finish (pop-ins, arcs). */
export function easeOutQuad(t: number): number {
  const c = clamp01(t);
  return 1 - (1 - c) * (1 - c);
}

/** One pooled particle. Slots are reused, never reallocated. */
export interface Particle {
  active: boolean;
  /** Position in game pixels. */
  x: number;
  y: number;
  /** Velocity in game pixels per second. */
  vx: number;
  vy: number;
  /** Downward acceleration in px/s² (0 = floaty sparkle). */
  gravity: number;
  color: string;
  /** Square side length in game pixels. */
  size: number;
  ageMs: number;
  lifeMs: number;
}

/** Fixed particle pool cap — key-mashing can never grow an unbounded array. */
export const PARTICLE_POOL_SIZE = 200;

/** Pre-allocate a pool of inactive particle slots. */
export function createParticlePool(size: number = PARTICLE_POOL_SIZE): Particle[] {
  return Array.from({ length: size }, () => ({
    active: false,
    x: 0,
    y: 0,
    vx: 0,
    vy: 0,
    gravity: 0,
    color: '',
    size: 1,
    ageMs: 0,
    lifeMs: 0,
  }));
}

export interface SpawnParticleOptions {
  x: number;
  y: number;
  vx?: number;
  vy?: number;
  gravity?: number;
  color: string;
  size?: number;
  lifeMs: number;
}

/** Activate a slot: the first inactive one, else recycle the oldest active. */
export function spawnParticle(pool: Particle[], opts: SpawnParticleOptions): void {
  let slot = pool.find((p) => !p.active);
  if (slot === undefined) {
    for (const p of pool) {
      if (slot === undefined || p.ageMs > slot.ageMs) {
        slot = p;
      }
    }
  }
  if (slot === undefined) {
    return; // zero-size pool
  }
  slot.active = true;
  slot.x = opts.x;
  slot.y = opts.y;
  slot.vx = opts.vx ?? 0;
  slot.vy = opts.vy ?? 0;
  slot.gravity = opts.gravity ?? 0;
  slot.color = opts.color;
  slot.size = opts.size ?? 1;
  slot.ageMs = 0;
  slot.lifeMs = opts.lifeMs;
}

/**
 * Advance every active particle by dtMs: semi-implicit Euler (gravity into
 * velocity first, then velocity into position), then age; slots past their
 * lifetime deactivate. Non-finite or negative dt counts as 0 (same policy
 * as core/fsm.ts).
 */
export function tickParticles(pool: Particle[], dtMs: number): void {
  const dt = Number.isFinite(dtMs) && dtMs > 0 ? dtMs : 0;
  const dtS = dt / 1000;
  for (const p of pool) {
    if (!p.active) {
      continue;
    }
    p.vy += p.gravity * dtS;
    p.x += p.vx * dtS;
    p.y += p.vy * dtS;
    p.ageMs += dt;
    if (p.ageMs >= p.lifeMs) {
      p.active = false;
    }
  }
}

/** Draw active particles as size×size squares, snapped to the pixel grid. */
export function drawParticles(ctx: SpriteCanvas, pool: Particle[]): void {
  for (const p of pool) {
    if (!p.active) {
      continue;
    }
    ctx.fillStyle = p.color;
    ctx.fillRect(Math.round(p.x), Math.round(p.y), p.size, p.size);
  }
}

// ---------------------------------------------------------------------------
// Death pixel-scatter (Manual M3): a dying monster's sprite decomposes into
// its own pixels as gravity particles — procedural, no death frames needed.
// ---------------------------------------------------------------------------

/** Scatter particle lifetime — matches the FSM's dying duration (500ms). */
export const SCATTER_LIFE_MS = 500;
/** Downward acceleration on scatter pixels, px/s². */
export const SCATTER_GRAVITY = 260;

/**
 * Spawn one gravity particle per opaque pixel of a sprite frame, at the
 * pixel's own position and palette color. Velocities radiate outward from
 * the sprite's horizontal center with a jitter derived from the pixel's own
 * coordinates — deterministic on purpose: no RNG draw is ever consumed, so
 * the engine's seeded event log and the tests stay reproducible.
 */
export function spawnSpriteScatter(
  pool: Particle[],
  sprite: Sprite,
  frame: number,
  x: number,
  y: number,
  scale = 1,
): void {
  const rows = sprite.frames[frame];
  if (rows === undefined) {
    return;
  }
  const centerX = x + (sprite.w * scale) / 2;
  for (let ry = 0; ry < sprite.h; ry++) {
    const row = rows[ry];
    if (row === undefined) {
      continue;
    }
    for (let rx = 0; rx < sprite.w; rx++) {
      const ch = row.charAt(rx);
      if (ch === TRANSPARENT || ch === '') {
        continue;
      }
      const color = sprite.palette[ch];
      if (color === undefined) {
        continue;
      }
      const px = x + rx * scale;
      spawnParticle(pool, {
        x: px,
        y: y + ry * scale,
        vx: (px - centerX) * 6 + ((rx * 31 + ry * 17) % 11) - 5,
        vy: -40 - ((rx * 13 + ry * 7) % 30),
        gravity: SCATTER_GRAVITY,
        color,
        size: scale,
        lifeMs: SCATTER_LIFE_MS,
      });
    }
  }
}

// ---------------------------------------------------------------------------
// Sparkles (level-up hero burst, drop-collection counter pop).
// ---------------------------------------------------------------------------

/** Sparkle particle lifetime, ms. */
export const SPARKLE_LIFE_MS = 600;
/** Default sparkle burst size. */
export const SPARKLE_COUNT = 12;

/**
 * Spawn a ring of floaty (gravity-free) sparkles around (x, y), alternating
 * yellow/white. Deterministic — directions come from the sparkle's index.
 */
export function spawnSparkles(
  pool: Particle[],
  x: number,
  y: number,
  count: number = SPARKLE_COUNT,
): void {
  for (let i = 0; i < count; i++) {
    const angle = (i / Math.max(1, count)) * Math.PI * 2;
    spawnParticle(pool, {
      x,
      y,
      vx: Math.cos(angle) * 28,
      vy: Math.sin(angle) * 28 - 22,
      gravity: 0,
      color: i % 2 === 0 ? COLORS.yellow : COLORS.white,
      lifeMs: SPARKLE_LIFE_MS,
    });
  }
}

